(function(){'use strict';
var FONT_KEY='welog-font-lock-v2',STATE_KEY='welog-pair-sheet-v4';
var sheet=document.getElementById('sheet'),controls=document.getElementById('controls');if(!sheet)return;
function norm(v){v=v||'';if(/^KoPub Dotum/.test(v))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v))return'KoPub Batang Medium';if(v==='__default__'||!v)return'Pretendard';return v}
function stack(v){v=norm(v);if(v==='KoPub Dotum Medium')return'"WeLog-Sheet-KoPubDotum",sans-serif';if(v==='KoPub Batang Medium')return'"WeLog-Sheet-KoPubBatang",serif';if(v==='Noto Sans KR')return'"WeLog-Sheet-Noto",sans-serif';if(v==='Pretendard')return'"WeLog-Sheet-Pretendard",sans-serif';if(v==='__system__')return'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';return '"'+String(v).replace(/"/g,'')+'","WeLog-Sheet-Noto",sans-serif'}
function stateFont(){try{return norm((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).font)}catch(e){return'Pretendard'}}
function locked(){return norm(localStorage.getItem(FONT_KEY)||stateFont())}
function applyFont(root){var f=stack(locked());document.documentElement.style.setProperty('--welog-locked-font',f);document.documentElement.style.setProperty('--welog-sheet-font',f);sheet.style.setProperty('--welog-sheet-font',f);sheet.style.setProperty('font-family',f,'important');(root||sheet).querySelectorAll('*').forEach(function(n){if(!n.closest('.direct-sticker'))n.style.setProperty('font-family',f,'important')});var sel=controls&&controls.querySelector('select[data-path="font"]');if(sel)for(var i=0;i<sel.options.length;i++)if(norm(sel.options[i].value)===locked()){sel.selectedIndex=i;break}}
function lock(v){v=norm(v);localStorage.setItem(FONT_KEY,v);try{var s=JSON.parse(localStorage.getItem(STATE_KEY)||'{}');s.font=v;localStorage.setItem(STATE_KEY,JSON.stringify(s))}catch(e){}applyFont()}
if(controls){controls.addEventListener('change',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true);controls.addEventListener('input',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true)}
document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#tabs'))setTimeout(applyFont,30)},true);window.addEventListener('pageshow',applyFont);document.addEventListener('visibilitychange',function(){if(!document.hidden)applyFont()});applyFont();
function stripEditor(root){root.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.st-v2-lock,.st-v2-del,.st-v2-resize,.direct-crop-ui,.guide-line').forEach(function(n){n.remove()});root.querySelectorAll('.direct-sticker').forEach(function(n){n.style.outline='none'})}
function makeModal(){var old=document.querySelector('.welog-exact-shot');if(old)old.remove();var m=document.createElement('div');m.className='welog-exact-shot';m.hidden=true;m.innerHTML='<section class="welog-exact-shot-dialog"><header class="welog-exact-shot-head"><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" aria-label="닫기">×</button></header><div class="welog-exact-shot-body"><div class="welog-preview-viewport"><div class="welog-preview-stage"></div></div></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('.welog-exact-shot-head button'))m.hidden=true});return m}
function preview(){applyFont();var m=makeModal(),body=m.querySelector('.welog-exact-shot-body'),viewport=m.querySelector('.welog-preview-viewport'),stage=m.querySelector('.welog-preview-stage');var clone=sheet.cloneNode(true);clone.removeAttribute('id');clone.classList.add('welog-preview-live-clone');stripEditor(clone);var f=stack(locked());clone.style.setProperty('--welog-sheet-font',f);clone.style.setProperty('font-family',f,'important');clone.style.setProperty('margin','0','important');clone.style.setProperty('transform','none','important');clone.style.setProperty('zoom','1','important');clone.querySelectorAll('*').forEach(function(n){if(!n.closest('.direct-sticker'))n.style.setProperty('font-family',f,'important')});stage.appendChild(clone);m.hidden=false;requestAnimationFrame(function(){requestAnimationFrame(function(){var w=Math.max(1,sheet.scrollWidth,sheet.offsetWidth),h=Math.max(1,sheet.scrollHeight,sheet.offsetHeight),bw=Math.max(1,body.clientWidth-32),bh=Math.max(1,body.clientHeight-32),scale=Math.min(1,bw/w,bh/h);viewport.style.width=(w*scale)+'px';viewport.style.height=(h*scale)+'px';stage.style.width=w+'px';stage.style.height=h+'px';stage.style.transform='scale('+scale+')';stage.style.transformOrigin='top left';clone.style.setProperty('width',w+'px','important');clone.style.setProperty('height',h+'px','important')})})}
async function ready(){applyFont();if(document.fonts){try{await document.fonts.ready}catch(e){console.warn('font readiness skipped',e)}}var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
function captureSize(){var oldTransform=sheet.style.transform,oldZoom=sheet.style.zoom;sheet.style.transform='none';sheet.style.zoom='1';var r=sheet.getBoundingClientRect(),w=Math.max(1,Math.ceil(sheet.scrollWidth),Math.ceil(sheet.offsetWidth),Math.ceil(r.width)),h=Math.max(1,Math.ceil(sheet.scrollHeight),Math.ceil(sheet.offsetHeight),Math.ceil(r.height));sheet.style.transform=oldTransform;sheet.style.zoom=oldZoom;return{w:w,h:h}}
function roundedMask(src,w){var ratio=src.width/Math.max(1,w),radius=parseFloat(getComputedStyle(sheet).borderRadius)||0,r=radius*ratio,out=document.createElement('canvas');out.width=src.width;out.height=src.height;var c=out.getContext('2d');c.clearRect(0,0,out.width,out.height);c.beginPath();c.moveTo(r,0);c.arcTo(out.width,0,out.width,out.height,r);c.arcTo(out.width,out.height,0,out.height,r);c.arcTo(0,out.height,0,0,r);c.arcTo(0,0,out.width,0,r);c.closePath();c.clip();c.drawImage(src,0,0);return out}
async function canvasPng(){await ready();if(!window.html2canvas)throw new Error('html2canvas unavailable');var size=captureSize(),f=stack(locked());var raw=await window.html2canvas(sheet,{scale:2,useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,width:size.w,height:size.h,scrollX:0,scrollY:0,windowWidth:Math.max(window.innerWidth,size.w+64),windowHeight:Math.max(window.innerHeight,size.h+64),onclone:function(doc){var s=doc.getElementById('sheet');if(!s)return;stripEditor(s);s.style.setProperty('--welog-sheet-font',f);s.style.setProperty('font-family',f,'important');s.style.setProperty('transform','none','important');s.style.setProperty('zoom','1','important');s.style.setProperty('margin','0','important');s.style.setProperty('width',size.w+'px','important');s.style.setProperty('height',size.h+'px','important');s.querySelectorAll('*').forEach(function(n){if(!n.closest('.direct-sticker'))n.style.setProperty('font-family',f,'important')})}});return roundedMask(raw,size.w)}
async function save(){var btn=document.getElementById('printBtn');if(!btn)return;var old=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';try{var canvas=await canvasPng(),blob=await new Promise(function(resolve,reject){canvas.toBlob(function(b){b?resolve(b):reject(new Error('PNG blob failed'))},'image/png')});var url=URL.createObjectURL(blob),a=document.createElement('a'),name='WeLog';try{name=((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).pairName||name).trim()||name}catch(e){}a.href=url;a.download=name+'.png';a.style.display='none';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(url)},1500)}catch(e){console.error('WeLog PNG failed',e);alert('PNG 저장에 실패했습니다. 다시 시도해 주세요.')}finally{btn.disabled=false;btn.textContent=old}}
function replace(id,fn){var old=document.getElementById(id);if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id=id;b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();fn()},true)}
replace('previewBtn',preview);replace('printBtn',save);
})();